def size_firecracker_fleet(hops_per_sec: float = 8333.0, render_ratio: float = 0.40, dwell_sec: float = 3.0) -> dict:
    render_qps = hops_per_sec * render_ratio
    base_tabs = render_qps * dwell_sec
    provisioned_tabs = int(base_tabs * 1.20)
    ram_tb = (provisioned_tabs * 432) / (1024 * 1024 * 0.95)
    return {"render_qps": round(render_qps, 1), "provisioned_tabs": provisioned_tabs, "ram_tb": round(ram_tb, 2)}

