def acquire_domain_slot(domain_tokens: int, circuit_state: str) -> str:
    if circuit_state == "OPEN":
        return "DEFER_120S"
    if domain_tokens <= 0:
        return "BACKOFF_JITTER"
    return "PERMIT_GRANTED"

def wrap_untrusted_span(span_id: str, clean_text: str, injection_score: float) -> str:
    if injection_score > 0.85:
        return f'<quarantined_span id="{span_id}" reason="prompt_injection_detected"/>'
    return f'<untrusted_source span_id="{span_id}">{clean_text}</untrusted_source>'

def filter_grounded_claims(claims: list[dict], span_store: dict, nli_fn, tau: float = 0.82) -> list[dict]:
    verified = []
    for c in claims:
        premises = [span_store[sid] for sid in c.get("span_ids", []) if sid in span_store]
        if premises and max(nli_fn(p, c["text"]) for p in premises) >= tau:
            verified.append(c)
    return verified

def evaluate_branch_health(spent_ratio: float, max_cosine_sim: float) -> str:
    if spent_ratio >= 1.0:
        return "FORCE_SYNTHESIS"
    if max_cosine_sim > 0.92:
        return "PRUNE_SEMANTIC_LOOP"
    if spent_ratio >= 0.85:
        return "ROUTE_SLM_TIER"
    return "CONTINUE_FRONTIER"
